	iconColor = row["stateColor"] or row["stateTypeColor"] if row["enabled"] else '--kcGray-50'
	rows.append([row["stateId"], row["stateName"], row["statePath"], row["stateCategoryId"], row["stateCategoryName"], row["stateCategoryPath"], row["stateTypeName"], row["iconPath"], row["enabled"], iconColor])

for row in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getStateCategory({})):
	iconColor = '--kcGray-50' if not row["enabled"] else None
	rows.append([None, None, row["stateCategoryPath"], row["stateCategoryId"], row["stateCategoryName"], row["stateCategoryPath"], None, None, row["enabled"], iconColor])

return system.dataset.toDataSet(headers, rows)

