config.script:
stateAssetLinkId = self.props.data.getValueAt(event.row, 'stateAssetLinkId')
userId = self.view.custom.security.userId
userAction = self.view.custom.assetStates.userAction

if userAction['canUpdate']:
	if event.column in ('enabled', 'selectable'): 
		retVal, msg = system.kanoa.asset.updateAssetStateLinkField(stateAssetLinkId, event.column, event.value, userId)
		if msg: system.perspective.sendMessage('showWarningToast', {'message': msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'state link has been changed'})
	elif event.column == 'stateCode':
		retVal, msg = system.kanoa.asset.setAssetStateLinkCode(stateAssetLinkId, event.value, self.view.custom.security.userId)
		if msg is not None: system.perspective.sendMessage('showWarningToast', {'message': msg})
		else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'state Code has been set'})
	else: system.perspective.sendMessage('showFailerToast', 'Column is not enabled for editing.')
	self.view.refreshBinding("custom.assetStates.data")
else: system.perspective.sendMessage('showFailerToast', 'No permissions to update states or no state selected.')

self.props.selection.selectedColumn = None
self.props.selection.selectedRow = None

return

